        # PESTAÑA 4: Veredicto Financiero
        self._agregar_banner_seccion_word(doc, "PESTAÑA 4: DICTAMEN DE RENTABILIDAD Y RETORNO SOBRE INVERSIÓN (ROI)", "065F46")
